// App code: what a tap on the photo does, swipes, keys, opening and closing, and placing the viewer full-screen.
import type { Example } from "../example.ts"
import { iconButton } from "./icon-button.ts"
import { html, type TemplateResult } from "lit-html"

export type PhotoViewerControls = "shown" | "hidden"
export type PhotoViewerStep = { label: string; onClick?: (event: MouseEvent) => void }
export type PhotoViewerProps = {
  src: string
  alt: string
  controls: PhotoViewerControls
  closeLabel: string
  onClose?: (event: MouseEvent) => void
  /** Drawn only when given, from the sm breakpoint up. */
  previous?: PhotoViewerStep
  next?: PhotoViewerStep
  /** Drawn under the photo until the photo paints, e.g. the grid's thumbnail. No layer when absent. */
  placeholder?: string
  /** The bottom bar's content. No bar when absent. */
  info?: TemplateResult
  /** A click on the photo only; clicks on the controls and the info bar never reach it. */
  onPhotoTap?: (event: MouseEvent) => void
  class?: string
}

// Hidden controls are invisible: not drawn, not tappable, not focusable.
const visibility: Record<PhotoViewerControls, string> = { shown: "visible", hidden: "invisible" }

const close = html`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18" /></svg>`
const chevronLeft = html`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7" /></svg>`
const chevronRight = html`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5l7 7-7 7" /></svg>`

function chip(step: PhotoViewerStep & { icon: TemplateResult }): TemplateResult {
  return iconButton({ ...step, variant: "soft", color: "gray", size: "3", radius: "full" })
}

export function photoViewer(props: PhotoViewerProps): TemplateResult {
  const shown = visibility[props.controls]
  const root = `relative h-full w-full overflow-hidden bg-black text-fg`
  const previous = props.previous
  const next = props.next
  return html`<div data-theme="dark" data-controls=${props.controls} class=${props.class === undefined ? root : `${root} ${props.class}`}>
    <div data-part="photo" class="absolute inset-0 flex touch-none select-none items-center justify-center" @click=${props.onPhotoTap}>
      ${props.placeholder === undefined ? "" : html`<img data-part="placeholder" class="absolute inset-0 h-full w-full object-contain" src=${props.placeholder} alt="" aria-hidden="true" referrerpolicy="no-referrer" draggable="false">`}
      <img class="relative h-full w-full object-contain" src=${props.src} alt=${props.alt} referrerpolicy="no-referrer" draggable="false">
    </div>
    <div data-part="top" class="pointer-events-none absolute inset-x-0 top-0 flex justify-end pt-[env(safe-area-inset-top)]">
      <div class="pointer-events-auto p-3 ${shown}">${chip({ icon: close, label: props.closeLabel, onClick: props.onClose })}</div>
    </div>
    ${previous === undefined ? "" : html`<div data-part="previous" class="absolute left-2 top-1/2 hidden -translate-y-1/2 sm:block ${shown}">${chip({ ...previous, icon: chevronLeft })}</div>`}
    ${next === undefined ? "" : html`<div data-part="next" class="absolute right-2 top-1/2 hidden -translate-y-1/2 sm:block ${shown}">${chip({ ...next, icon: chevronRight })}</div>`}
    ${props.info === undefined ? "" : html`<div data-part="info" class="absolute inset-x-0 bottom-0 bg-canvas/90 pb-[env(safe-area-inset-bottom)] ${shown}"><div class="px-4 py-3">${props.info}</div></div>`}
  </div>`
}

const picture = `data:image/svg+xml,${encodeURIComponent(
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 90 160"><defs><linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#7cc4f2"/><stop offset="1" stop-color="#f6e3b4"/></linearGradient></defs><rect width="90" height="160" fill="url(#s)"/><path d="M0 130 Q30 90 60 120 T90 110 V160 H0Z" fill="#3f8f5b"/></svg>`,
)}`

export const variants = { controls: ["shown", "hidden"] satisfies PhotoViewerControls[] }

export const sample = {
  src: picture,
  alt: "beach.jpg",
  closeLabel: "Close",
  previous: { label: "Previous photo" },
  next: { label: "Next photo" },
  info: html`<p class="text-xs text-muted">Anna · added 2 hours ago</p><p class="text-xs text-fg">On Anna's and your phone</p>`,
  class: "aspect-[9/16] w-full",
} satisfies Omit<PhotoViewerProps, keyof typeof variants>

